using UrlShortener.Application.Links;
using Xunit;

namespace UrlShortener.UnitTests;

public sealed class UrlNormalizerTests
{
    [Theory]
    [InlineData(
        "HTTP://ExAmPlE.Com:80/a/b?keep=a%2Fb&uTm_source=one&notutm_term=x&utmx=y#Section",
        "http://example.com/a/b?keep=a%2Fb&notutm_term=x&utmx=y#Section")]
    [InlineData(
        "HTTPS://ExAMPLE.Com:443/path?UtM_source=x&utm_campaign=y#frag",
        "https://example.com/path#frag")]
    [InlineData(
        "HtTp://ExAMPLE.Com:8080/path?utm_source=x&keep=a%2Fb#Frag",
        "http://example.com:8080/path?keep=a%2Fb#Frag")]
    [InlineData(
        "HTTPS://ExAMPLE.Com/path?keep=one&utm_source=two&keep=three",
        "https://example.com/path?keep=one&keep=three")]
    [InlineData(
        "https://example.com/path?utm_source=one&utm_campaign=two#fragment",
        "https://example.com/path#fragment")]
    [InlineData(
        "https://example.com/path?utm_source=one&&#fragment",
        "https://example.com/path#fragment")]
    [InlineData(
        "https://example.com/path?notutm_source=one&utmx=two",
        "https://example.com/path?notutm_source=one&utmx=two")]
    [InlineData(
        "https://example.com/path#fragment",
        "https://example.com/path#fragment")]
    public void NormalizeAppliesOnlyRequestedUrlTransformations(string submittedUrl, string expectedUrl)
    {
        Assert.Equal(expectedUrl, UrlNormalizer.Normalize(submittedUrl));
    }

    [Fact]
    public void NormalizeRejectsNullInput()
    {
        Assert.Throws<ArgumentNullException>(() => UrlNormalizer.Normalize(null!));
    }

    [Theory]
    [InlineData("/relative/path")]
    [InlineData("ftp://example.com/file")]
    [InlineData("not a URL")]
    [InlineData("http://")]
    public void NormalizeRejectsInvalidOrUnsupportedUrls(string submittedUrl)
    {
        Assert.Throws<ArgumentException>(() => UrlNormalizer.Normalize(submittedUrl));
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using UrlShortener.Application.Links;
using UrlShortener.Infrastructure;
using Xunit;

namespace UrlShortener.IntegrationTests;

public sealed class UrlNormalizationPersistenceApiTests(ApiFactory factory) : IClassFixture<ApiFactory>
{
    [Fact]
    public async Task CreateLinkReturnsAndPersistsNormalizedDestination()
    {
        using var client = factory.Client();
        const string submittedUrl = "HTTPS://ExAMPLE.Com:443/path?keep=a%2Fb&UtM_Source=campaign#section";
        const string expectedUrl = "https://example.com/path?keep=a%2Fb#section";

        using var response = await client.PostAsJsonAsync(
            "/api/v1/links", new CreateLinkRequest(submittedUrl));

        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
        var created = await response.Content.ReadFromJsonAsync<LinkResponse>();
        Assert.NotNull(created);
        Assert.Equal(expectedUrl, created.LongUrl);

        await using var scope = factory.Services.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        var saved = await db.ShortLinks.AsNoTracking()
            .SingleAsync(link => link.Code == created.Code);
        Assert.Equal(expectedUrl, saved.LongUrl);
    }

    [Fact]
    public async Task InvalidDestinationReturnsProblemDetails()
    {
        using var client = factory.Client();
        using var response = await client.PostAsJsonAsync(
            "/api/v1/links", new CreateLinkRequest("javascript:alert(1)"));

        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
        Assert.Equal("application/problem+json", response.Content.Headers.ContentType!.MediaType);

        var bodyText = await response.Content.ReadAsStringAsync();
        using var body = JsonDocument.Parse(bodyText);
        Assert.Equal((int)HttpStatusCode.BadRequest, body.RootElement.GetProperty("status").GetInt32());
    }
}
